insert into anybike_publishing.riding_style_pages(slug,content) values
('directory','{"featured": [], "categories": [], "title": "Motorcycle Types & Riding Styles", "lead": "Find motorcycles by how you want to ride, compare related types and explore manufacturer and model guides. These are research pages, not live stock listings.", "stories": ["/global/yamaha-niken-leaning-three-wheel-design.html", "/global/itchy-boots-japan-coastal-ride.html", "/global/suzuki-rm250-motocross-suspension-history.html"]}'::jsonb),
('adventure','{"intro": "Adventure motorcycles combine upright riding positions, useful luggage options and the ability to handle varied roads. Some are principally road-tourers; others favour lighter weight and unsealed routes.", "featured": [77, 442, 290, 255, 104, 520], "consider": [["Road versus off-road", "Wheel sizes, suspension travel and tyre choice influence comfort on tarmac and rough routes."], ["Weight and seat height", "Consider low-speed manoeuvring with luggage, and whether both feet reach the ground comfortably."], ["Travel capability", "Range, luggage mounting, wind protection and passenger comfort matter on longer trips."]], "related": ["touring", "off-road", "roadsters"], "categories": ["Adventure", "Adventure & GS", "Dual Sport", "Rally"], "title": "Adventure Motorcycles", "lead": "Browse adventure motorcycles across motorcycle manufacturers, including earlier and discontinued models. Find related styles and read motorcycle research on AnyBike Global.", "stories": ["/global/royal-enfield-himalayan-india-mountain-roads.html", "/global/itchy-boots-japan-coastal-ride.html", "/global/can-am-pulse-origin-electric-motorcycles.html"]}'::jsonb),
('touring','{"intro": "Touring motorcycles prioritise comfort on longer journeys, passenger accommodation, wind protection and luggage. They range from purpose-built luxury tourers to lighter sport-tourers.", "featured": [49, 455, 701, 558, 234, 182], "consider": [["Comfort", "Try the riding position, screen and weather protection over a realistic distance."], ["Weight", "Fully loaded weight and low-speed handling can matter more than quoted power."], ["Luggage", "Check factory cases, payload limits and passenger accommodation."]], "related": ["adventure", "roadsters", "cruisers"], "categories": ["Touring", "Sports Touring", "Sport Touring", "Touring & Roadsters"], "title": "Touring Motorcycles", "lead": "Browse touring motorcycles across motorcycle manufacturers, including earlier and discontinued models. Find related styles and read motorcycle research on AnyBike Global.", "stories": ["/global/itchy-boots-japan-coastal-ride.html", "/global/yamaha-niken-leaning-three-wheel-design.html", "/global/honda-gold-wing-dct-grand-touring.html"]}'::jsonb),
('sports','{"intro": "Sports motorcycles emphasise handling, braking and aerodynamic performance. The category includes road-friendly middleweights and track-focused superbikes.", "featured": [90, 107, 171, 719, 499, 3], "consider": [["Road or track", "Riding position, heat and suspension setup differ considerably by model."], ["Running costs", "Check tyres, insurance, servicing and evidence of regular maintenance."], ["Electronics", "Riding modes and assistance systems vary by generation and specification."]], "related": ["roadsters", "touring"], "categories": ["Sports", "Sport", "Sport & Performance", "Racing"], "title": "Sports & Superbikes", "lead": "Browse sports & superbikes across motorcycle manufacturers, including earlier and discontinued models. Find related styles and read motorcycle research on AnyBike Global.", "stories": ["/global/bimota-tesi-h2-blimey-look-at-that.html", "/global/yamaha-niken-leaning-three-wheel-design.html", "/global/ducati-diavel-v4-i-want-one.html"]}'::jsonb),
('roadsters','{"intro": "Naked motorcycles and roadsters offer upright road riding and accessible performance without the full bodywork of a sports bike.", "featured": [89, 275, 250, 404, 443, 203], "consider": [["Wind protection", "Minimal fairings are enjoyable locally but less sheltered at motorway speeds."], ["Ergonomics", "Handlebar width, seat height and footpeg position determine day-to-day comfort."], ["Engine character", "Compare low-rev flexibility, vibration and throttle response, not just peak output."]], "related": ["sports", "classics", "touring"], "categories": ["Roadsters", "Roadster", "Naked & Roadsters"], "title": "Naked & Roadster Motorcycles", "lead": "Browse naked & roadster motorcycles across motorcycle manufacturers, including earlier and discontinued models. Find related styles and read motorcycle research on AnyBike Global.", "stories": ["/global/bajaj-pulsar-indian-motorcycle-evolution.html", "/global/can-am-pulse-origin-electric-motorcycles.html", "/global/ducati-diavel-v4-i-want-one.html"]}'::jsonb),
('classics','{"intro": "Classic and heritage motorcycles draw on historic design, engineering and riding culture, from authentic older machines to modern retro interpretations.", "featured": [377, 663, 628, 561, 384, 204], "consider": [["Original or modern", "Classic ownership and a modern retro differ in maintenance and parts supply."], ["Condition", "Check corrosion, originality, service history and any restoration claims."], ["Intended use", "Balance character and styling with brakes, comfort and daily usability."]], "related": ["roadsters", "cruisers"], "categories": ["Classics", "Classic", "Modern Classics", "Heritage & Historic", "Heritage / Cruiser"], "title": "Classic & Heritage Motorcycles", "lead": "Browse classic & heritage motorcycles across motorcycle manufacturers, including earlier and discontinued models. Find related styles and read motorcycle research on AnyBike Global.", "stories": ["/global/burt-munro-worlds-fastest-indian.html", "/global/indian-scout-chief-and-springfield-history.html", "/global/royal-enfield-himalayan-india-mountain-roads.html"]}'::jsonb),
('cruisers','{"intro": "Cruiser motorcycles emphasise relaxed road riding, distinctive styling and low-seat ergonomics. Weight, footpeg position and touring suitability vary widely.", "featured": [157, 485, 666, 823, 402, 915], "consider": [["Riding position", "Forward foot controls and bar reach may not suit every rider."], ["Mass and manoeuvring", "Check steering lock, weight and storage requirements."], ["Passenger use", "Seat, luggage and suspension options differ greatly."]], "related": ["touring", "classics"], "categories": ["Cruisers", "Heritage / Cruiser"], "title": "Cruiser Motorcycles", "lead": "Browse cruiser motorcycles across motorcycle manufacturers, including earlier and discontinued models. Find related styles and read motorcycle research on AnyBike Global.", "stories": ["/global/ducati-diavel-v4-i-want-one.html", "/global/burt-munro-worlds-fastest-indian.html", "/global/indian-scout-chief-and-springfield-history.html"]}'::jsonb),
('scooters','{"intro": "Scooters and automatic motorcycles focus on practical mobility. Urban commuters, electric scooters and larger long-distance models serve quite different needs.", "featured": [27, 179, 309, 680, 689, 460], "consider": [["Licence and use", "Check licensing category, intended speeds and passenger requirements."], ["Practicality", "Storage, weather protection and parking are key everyday advantages."], ["Electric range", "For electric models, check actual use, charging access and battery warranty."]], "related": ["roadsters", "touring"], "categories": ["Scooters", "Electric Scooters", "Scooter / Electric", "Adventure Scooters", "Underbone"], "title": "Scooters & Automatic Motorcycles", "lead": "Browse scooters & automatic motorcycles across motorcycle manufacturers, including earlier and discontinued models. Find related styles and read motorcycle research on AnyBike Global.", "stories": ["/global/honda-nm4-vultus-did-you-know.html", "/anybike-global.html#global-story-honda-super-cub-the-small-motorcycle-with-a-global-story", "/anybike-global.html#global-story-vespa-how-practical-transport-became-a-design-icon"]}'::jsonb),
('off-road','{"intro": "Off-road and enduro motorcycles are intended for trails, competition or demanding surfaces. Road legality and maintenance intervals differ from general adventure bikes.", "featured": [530, 469, 344, 453, 712, 421], "consider": [["Road legality", "Check registration, lights and legal access before planning road or trail use."], ["Service intervals", "Competition-derived bikes can require substantially more frequent maintenance."], ["Suitability", "Tyres, gearing, weight and suspension should match the terrain and rider experience."]], "related": ["adventure", "sports"], "categories": ["Off-road", "Motocross", "Trials", "Dual Sport", "Rally"], "title": "Off-road & Enduro Motorcycles", "lead": "Browse off-road & enduro motorcycles across motorcycle manufacturers, including earlier and discontinued models. Find related styles and read motorcycle research on AnyBike Global.", "stories": ["/global/suzuki-rm250-motocross-suspension-history.html", "/global/royal-enfield-himalayan-india-mountain-roads.html", "/global/yamaha-yz250-1974-monocross-history.html"]}'::jsonb);
create function public.public_anybike_riding_style_v1(p_slug text)
returns jsonb language sql stable security definer set search_path='' as $$
select p.content || jsonb_build_object('stories',(
 select coalesce(jsonb_agg(m.media || jsonb_build_object('url',s.story_url,'title',s.headline,'summary',s.summary) order by a.ordinality),'[]'::jsonb)
 from jsonb_array_elements_text(p.content->'stories') with ordinality a(url,ordinality)
 join public.motorcycle_global_stories_v1 s on s.story_url=a.url and s.editorial_status='published'
 join anybike_publishing.riding_story_media m on m.story_url=s.story_url
), 'logos',(select jsonb_object_agg(m.display_name,jsonb_build_object('image',m.public_logo_url,'background',m.public_logo_background))
 from public.motorcycle_catalog_manufacturers m where m.public_logo_url like 'https://%'),
 'relatedNames',(select jsonb_object_agg(b.slug,b.content->>'title') from anybike_publishing.riding_style_pages b))
from anybike_publishing.riding_style_pages p where p.slug=p_slug;
$$;
revoke all on function public.public_anybike_riding_style_v1(text) from public;
grant execute on function public.public_anybike_riding_style_v1(text) to anon,authenticated;
